/** static bool32 IsPlayerDefeated(u32 battleOutcome) */
export function IsPlayerDefeated(battleOutcome: any): any {
  switch (battleOutcome)
      {
      case B_OUTCOME_LOST:
      case B_OUTCOME_DREW:
          return TRUE;
      case B_OUTCOME_WON:
      case B_OUTCOME_RAN:
      case B_OUTCOME_PLAYER_TELEPORTED:
      case B_OUTCOME_MON_FLED:
      case B_OUTCOME_CAUGHT:
          return FALSE;
      default:
          return FALSE;
      }
}

