/** static inline void SetU8(void *ptr, u8 value) */
export function SetU8(ptr: any, value: any): any {
  MEM_WRITE(ptr, value);
}

/** static inline void SetU16(void *ptr, u16 value) */
export function SetU16(ptr: any, value: any): any {
  MEM_WRITE(ptr, value);
}

/** static inline void SetU32(void *ptr, u32 value) */
export function SetU32(ptr: any, value: any): any {
  MEM_WRITE(ptr, value);
}

/** static inline void SetPtr(const void *ptr, const void *value) */
export function SetPtr(ptr: any, value: any): any {
  (ptr) = value;
}

/** static void TrainerBattleLoadArgs(const struct TrainerBattleParameter *specs, const u8 *data) */
export function TrainerBattleLoadArgs(specs: any, data: any): any {
  while (1)
      {
          switch (specs.ptrType)
          {
          case TRAINER_PARAM_LOAD_VAL_8BIT:
              SetU8(specs.varPtr, TrainerBattleLoadArg8(data));
              data += 1;
              break;
          case TRAINER_PARAM_LOAD_VAL_16BIT:
              SetU16(specs.varPtr, TrainerBattleLoadArg16(data));
              data += 2;
              break;
          case TRAINER_PARAM_LOAD_VAL_32BIT:
              SetU32(specs.varPtr, TrainerBattleLoadArg32(data));
              data += 4;
              break;
          case TRAINER_PARAM_CLEAR_VAL_8BIT:
              SetU8(specs.varPtr, 0);
              break;
          case TRAINER_PARAM_CLEAR_VAL_16BIT:
              SetU16(specs.varPtr, 0);
              break;
          case TRAINER_PARAM_CLEAR_VAL_32BIT:
              SetU32(specs.varPtr, 0);
              break;
          case TRAINER_PARAM_LOAD_SCRIPT_RET_ADDR:
              SetPtr(specs.varPtr, data);
              return;
          }
          specs++;
      }
}

