/** void BattleSetup_StartTrainerBattle(void) */
export function BattleSetup_StartTrainerBattle(): any {
  if (gNoOfApproachingTrainers == 2)
          gBattleTypeFlags = (BATTLE_TYPE_DOUBLE | BATTLE_TYPE_TWO_OPPONENTS | BATTLE_TYPE_TRAINER);
      else
          gBattleTypeFlags = (BATTLE_TYPE_TRAINER);

      if (CurrentBattlePyramidLocation() != PYRAMID_LOCATION_NONE)
      {
          VarSet(VAR_TEMP_PLAYING_PYRAMID_MUSIC, 0);
          gBattleTypeFlags |= BATTLE_TYPE_PYRAMID;

          if (gNoOfApproachingTrainers == 2)
          {
              FillFrontierTrainersParties(1);
              ZeroMonData(gEnemyParty[1]);
              ZeroMonData(gEnemyParty[2]);
              ZeroMonData(gEnemyParty[4]);
              ZeroMonData(gEnemyParty[5]);
          }
          else
          {
              FillFrontierTrainerParty(1);
              ZeroMonData(gEnemyParty[1]);
              ZeroMonData(gEnemyParty[2]);
          }

          MarkApproachingPyramidTrainersAsBattled();
      }
      else if (InTrainerHillChallenge())
      {
          gBattleTypeFlags |= BATTLE_TYPE_TRAINER_HILL;

          if (gNoOfApproachingTrainers == 2)
              FillHillTrainersParties();
          else
              FillHillTrainerParty();

          SetHillTrainerFlag();
      }

      sNoOfPossibleTrainerRetScripts = gNoOfApproachingTrainers;
      gNoOfApproachingTrainers = 0;
      sShouldCheckTrainerBScript = FALSE;
      gWhichTrainerToFaceAfterBattle = 0;
      gMain.savedCallback = CB2_EndTrainerBattle;

      if (CurrentBattlePyramidLocation() != PYRAMID_LOCATION_NONE || InTrainerHillChallenge())
          DoBattlePyramidTrainerHillBattle();
      else
          DoTrainerBattle();

      ScriptContext_Stop();
}

/** static void CB2_EndTrainerBattle(void) */
export function CB2_EndTrainerBattle(): any {
  if (gTrainerBattleOpponent_A == TRAINER_SECRET_BASE)
      {
          SetMainCallback2(CB2_ReturnToFieldContinueScriptPlayMapMusic);
      }
      else if (IsPlayerDefeated(gBattleOutcome) == TRUE)
      {
          if (CurrentBattlePyramidLocation() != PYRAMID_LOCATION_NONE || InTrainerHillChallenge())
              SetMainCallback2(CB2_ReturnToFieldContinueScriptPlayMapMusic);
          else
              SetMainCallback2(CB2_WhiteOut);
      }
      else
      {
          SetMainCallback2(CB2_ReturnToFieldContinueScriptPlayMapMusic);
          if (CurrentBattlePyramidLocation() == PYRAMID_LOCATION_NONE && !InTrainerHillChallenge())
          {
              RegisterTrainerInMatchCall();
              SetBattledTrainersFlags();
          }
      }
}

/** static void CB2_EndRematchBattle(void) */
export function CB2_EndRematchBattle(): any {
  if (gTrainerBattleOpponent_A == TRAINER_SECRET_BASE)
      {
          SetMainCallback2(CB2_ReturnToFieldContinueScriptPlayMapMusic);
      }
      else if (IsPlayerDefeated(gBattleOutcome) == TRUE)
      {
          SetMainCallback2(CB2_WhiteOut);
      }
      else
      {
          SetMainCallback2(CB2_ReturnToFieldContinueScriptPlayMapMusic);
          RegisterTrainerInMatchCall();
          SetBattledTrainersFlags();
          HandleRematchVarsOnBattleEnd();
      }
}

/** void BattleSetup_StartRematchBattle(void) */
export function BattleSetup_StartRematchBattle(): any {
  gBattleTypeFlags = BATTLE_TYPE_TRAINER;
      gMain.savedCallback = CB2_EndRematchBattle;
      DoTrainerBattle();
      ScriptContext_Stop();
}

/** void ShowTrainerIntroSpeech(void) */
export function ShowTrainerIntroSpeech(): any {
  if (CurrentBattlePyramidLocation() != PYRAMID_LOCATION_NONE)
      {
          if (gNoOfApproachingTrainers == 0 || gNoOfApproachingTrainers == 1)
              CopyPyramidTrainerSpeechBefore(LocalIdToPyramidTrainerId(gSpecialVar_LastTalked));
          else
              CopyPyramidTrainerSpeechBefore(LocalIdToPyramidTrainerId(gObjectEvents[gApproachingTrainers[gApproachingTrainerId].objectEventId].localId));

          ShowFieldMessageFromBuffer();
      }
      else if (InTrainerHillChallenge())
      {
          if (gNoOfApproachingTrainers == 0 || gNoOfApproachingTrainers == 1)
              CopyTrainerHillTrainerText(TRAINER_HILL_TEXT_INTRO, LocalIdToHillTrainerId(gSpecialVar_LastTalked));
          else
              CopyTrainerHillTrainerText(TRAINER_HILL_TEXT_INTRO, LocalIdToHillTrainerId(gObjectEvents[gApproachingTrainers[gApproachingTrainerId].objectEventId].localId));

          ShowFieldMessageFromBuffer();
      }
      else
      {
          ShowFieldMessage(GetIntroSpeechOfApproachingTrainer());
      }
}

/** void ShowTrainerCantBattleSpeech(void) */
export function ShowTrainerCantBattleSpeech(): any {
  ShowFieldMessage(GetTrainerCantBattleSpeech());
}

/** void PlayTrainerEncounterMusic(void) */
export function PlayTrainerEncounterMusic(): any {
  let trainerId: any = null;
      let music: any = null;

      if (gApproachingTrainerId == 0)
          trainerId = gTrainerBattleOpponent_A;
      else
          trainerId = gTrainerBattleOpponent_B;

      if (sTrainerBattleMode != TRAINER_BATTLE_CONTINUE_SCRIPT_NO_MUSIC
          && sTrainerBattleMode != TRAINER_BATTLE_CONTINUE_SCRIPT_DOUBLE_NO_MUSIC)
      {
          switch (GetTrainerEncounterMusicId(trainerId))
          {
          case TRAINER_ENCOUNTER_MUSIC_MALE:
              music = MUS_ENCOUNTER_MALE;
              break;
          case TRAINER_ENCOUNTER_MUSIC_FEMALE:
              music = MUS_ENCOUNTER_FEMALE;
              break;
          case TRAINER_ENCOUNTER_MUSIC_GIRL:
              music = MUS_ENCOUNTER_GIRL;
              break;
          case TRAINER_ENCOUNTER_MUSIC_INTENSE:
              music = MUS_ENCOUNTER_INTENSE;
              break;
          case TRAINER_ENCOUNTER_MUSIC_COOL:
              music = MUS_ENCOUNTER_COOL;
              break;
          case TRAINER_ENCOUNTER_MUSIC_AQUA:
              music = MUS_ENCOUNTER_AQUA;
              break;
          case TRAINER_ENCOUNTER_MUSIC_MAGMA:
              music = MUS_ENCOUNTER_MAGMA;
              break;
          case TRAINER_ENCOUNTER_MUSIC_SWIMMER:
              music = MUS_ENCOUNTER_SWIMMER;
              break;
          case TRAINER_ENCOUNTER_MUSIC_TWINS:
              music = MUS_ENCOUNTER_TWINS;
              break;
          case TRAINER_ENCOUNTER_MUSIC_ELITE_FOUR:
              music = MUS_ENCOUNTER_ELITE_FOUR;
              break;
          case TRAINER_ENCOUNTER_MUSIC_HIKER:
              music = MUS_ENCOUNTER_HIKER;
              break;
          case TRAINER_ENCOUNTER_MUSIC_INTERVIEWER:
              music = MUS_ENCOUNTER_INTERVIEWER;
              break;
          case TRAINER_ENCOUNTER_MUSIC_RICH:
              music = MUS_ENCOUNTER_RICH;
              break;
          default:
              music = MUS_ENCOUNTER_SUSPICIOUS;
          }
          PlayNewMapMusic(music);
      }
}

/** static s32 FirstBattleTrainerIdToRematchTableId(const struct RematchTrainer *table, u16 trainerId) */
export function FirstBattleTrainerIdToRematchTableId(table: any, trainerId: any): any {
  let i: any = null;

      for (i = 0; i < REMATCH_TABLE_ENTRIES; i++)
      {
          if (table[i].trainerIds[0] == trainerId)
              return i;
      }

      return -1;
}

/** static s32 TrainerIdToRematchTableId(const struct RematchTrainer *table, u16 trainerId) */
export function TrainerIdToRematchTableId(table: any, trainerId: any): any {
  let i, j;

      for (i = 0; i < REMATCH_TABLE_ENTRIES; i++)
      {
          for (j = 0; j < REMATCHES_COUNT; j++)
          {
              if (table[i].trainerIds[j] == 0) break;  
              if (table[i].trainerIds[j] == trainerId)
                  return i;
          }
      }

      return -1;
}

/** static bool32 IsRematchForbidden(s32 rematchTableId) */
export function IsRematchForbidden(rematchTableId: any): any {
  if (rematchTableId >= REMATCH_ELITE_FOUR_ENTRIES)
          return TRUE;
      else if (rematchTableId == REMATCH_WALLY_VR)
          return !FlagGet(FLAG_DEFEATED_WALLY_VICTORY_ROAD);
      else
          return FALSE;
}

/** static void SetRematchIdForTrainer(const struct RematchTrainer *table, u32 tableId) */
export function SetRematchIdForTrainer(table: any, tableId: any): any {
  let i: any = null;

      for (i = 1; i < REMATCHES_COUNT; i++)
      {
          let trainerId: any = table[tableId].trainerIds[i];

          if (trainerId == 0)
              break;
          if (!HasTrainerBeenFought(trainerId))
              break;
      }

      gSaveBlock1Ptr.trainerRematches[tableId] = i;
}

/** static bool32 UpdateRandomTrainerRematches(const struct RematchTrainer *table, u16 mapGroup, u16 mapNum) */
export function UpdateRandomTrainerRematches(table: any, mapGroup: any, mapNum: any): any {
  let i: any = null;
      let ret: any = FALSE;

      for (i = 0; i <= REMATCH_SPECIAL_TRAINER_START; i++)
      {
          if (table[i].mapGroup == mapGroup && table[i].mapNum == mapNum && !IsRematchForbidden(i))
          {
              if (gSaveBlock1Ptr.trainerRematches[i] != 0)
              {
                   
                  ret = TRUE;
              }
              else if (FlagGet(TRAINER_REGISTERED_FLAGS_START + i)
               && (Random() % 100) <= 30)   
              {
                  SetRematchIdForTrainer(table, i);
                  ret = TRUE;
              }
          }
      }

      return ret;
}

/** void UpdateRematchIfDefeated(s32 rematchTableId) */
export function UpdateRematchIfDefeated(rematchTableId: any): any {
  if (HasTrainerBeenFought(gRematchTable[rematchTableId].trainerIds[0]) == TRUE)
          SetRematchIdForTrainer(gRematchTable, rematchTableId);
}

/** static bool32 DoesSomeoneWantRematchIn_(const struct RematchTrainer *table, u16 mapGroup, u16 mapNum) */
export function DoesSomeoneWantRematchIn_(table: any, mapGroup: any, mapNum: any): any {
  let i: any = null;

      for (i = 0; i < REMATCH_TABLE_ENTRIES; i++)
      {
          if (table[i].mapGroup == mapGroup && table[i].mapNum == mapNum && gSaveBlock1Ptr.trainerRematches[i] != 0)
              return TRUE;
      }

      return FALSE;
}

/** static bool32 IsRematchTrainerIn_(const struct RematchTrainer *table, u16 mapGroup, u16 mapNum) */
export function IsRematchTrainerIn_(table: any, mapGroup: any, mapNum: any): any {
  let i: any = null;

      for (i = 0; i < REMATCH_TABLE_ENTRIES; i++)
      {
          if (table[i].mapGroup == mapGroup && table[i].mapNum == mapNum)
              return TRUE;
      }

      return FALSE;
}

/** static bool8 IsFirstTrainerIdReadyForRematch(const struct RematchTrainer *table, u16 firstBattleTrainerId) */
export function IsFirstTrainerIdReadyForRematch(table: any, firstBattleTrainerId: any): any {
  let tableId: any = FirstBattleTrainerIdToRematchTableId(table, firstBattleTrainerId);

      if (tableId == -1)
          return FALSE;
      if (tableId >= MAX_REMATCH_ENTRIES)
          return FALSE;
      if (gSaveBlock1Ptr.trainerRematches[tableId] == 0)
          return FALSE;

      return TRUE;
}

/** static bool8 IsTrainerReadyForRematch_(const struct RematchTrainer *table, u16 trainerId) */
export function IsTrainerReadyForRematch_(table: any, trainerId: any): any {
  let tableId: any = TrainerIdToRematchTableId(table, trainerId);

      if (tableId == -1)
          return FALSE;
      if (tableId >= MAX_REMATCH_ENTRIES)
          return FALSE;
      if (gSaveBlock1Ptr.trainerRematches[tableId] == 0)
          return FALSE;

      return TRUE;
}

/** static u16 GetRematchTrainerIdFromTable(const struct RematchTrainer *table, u16 firstBattleTrainerId) */
export function GetRematchTrainerIdFromTable(table: any, firstBattleTrainerId: any): any {
  let trainerEntry: any = null;
      let i: any = null;
      let tableId: any = FirstBattleTrainerIdToRematchTableId(table, firstBattleTrainerId);

      if (tableId == -1)
          return FALSE;

      trainerEntry =table[tableId];
      for (i = 1; i < REMATCHES_COUNT; i++)
      {
          if (trainerEntry.trainerIds[i] == 0)  
              return trainerEntry.trainerIds[i - 1];
          if (!HasTrainerBeenFought(trainerEntry.trainerIds[i]))
              return trainerEntry.trainerIds[i];
      }

      return trainerEntry.trainerIds[REMATCHES_COUNT - 1];
}

/** static u16 GetLastBeatenRematchTrainerIdFromTable(const struct RematchTrainer *table, u16 firstBattleTrainerId) */
export function GetLastBeatenRematchTrainerIdFromTable(table: any, firstBattleTrainerId: any): any {
  let trainerEntry: any = null;
      let i: any = null;
      let tableId: any = FirstBattleTrainerIdToRematchTableId(table, firstBattleTrainerId);

      if (tableId == -1)
          return FALSE;

      trainerEntry =table[tableId];
      for (i = 1; i < REMATCHES_COUNT; i++)
      {
          if (trainerEntry.trainerIds[i] == 0)  
              return trainerEntry.trainerIds[i - 1];
          if (!HasTrainerBeenFought(trainerEntry.trainerIds[i]))
              return trainerEntry.trainerIds[i - 1];
      }

      return trainerEntry.trainerIds[REMATCHES_COUNT - 1];
}

/** static void ClearTrainerWantRematchState(const struct RematchTrainer *table, u16 firstBattleTrainerId) */
export function ClearTrainerWantRematchState(table: any, firstBattleTrainerId: any): any {
  let tableId: any = TrainerIdToRematchTableId(table, firstBattleTrainerId);

      if (tableId != -1)
          gSaveBlock1Ptr.trainerRematches[tableId] = 0;
}

/** static u32 GetTrainerMatchCallFlag(u32 trainerId) */
export function GetTrainerMatchCallFlag(trainerId: any): any {
  let i: any = null;

      for (i = 0; i < REMATCH_TABLE_ENTRIES; i++)
      {
          if (gRematchTable[i].trainerIds[0] == trainerId)
              return TRAINER_REGISTERED_FLAGS_START + i;
      }

      return 0xFFFF;
}

/** static void RegisterTrainerInMatchCall(void) */
export function RegisterTrainerInMatchCall(): any {
  if (FlagGet(FLAG_HAS_MATCH_CALL))
      {
          let matchCallFlagId: any = GetTrainerMatchCallFlag(gTrainerBattleOpponent_A);
          if (matchCallFlagId != 0xFFFF)
              FlagSet(matchCallFlagId);
      }
}

/** static bool8 WasSecondRematchWon(const struct RematchTrainer *table, u16 firstBattleTrainerId) */
export function WasSecondRematchWon(table: any, firstBattleTrainerId: any): any {
  let tableId: any = FirstBattleTrainerIdToRematchTableId(table, firstBattleTrainerId);

      if (tableId == -1)
          return FALSE;
      if (!HasTrainerBeenFought(table[tableId].trainerIds[1]))
          return FALSE;

      return TRUE;
}

/** static bool32 HasAtLeastFiveBadges(void) */
export function HasAtLeastFiveBadges(): any {
  let i, count;

      for (count = 0, i = 0; i < ARRAY_COUNT(sBadgeFlags); i++)
      {
          if (FlagGet(sBadgeFlags[i]) == TRUE)
          {
              if (++count >= 5)
                  return TRUE;
          }
      }

      return FALSE;
}

/** void IncrementRematchStepCounter(void) */
export function IncrementRematchStepCounter(): any {
  if (HasAtLeastFiveBadges())
      {
          if (gSaveBlock1Ptr.trainerRematchStepCounter >= STEP_COUNTER_MAX)
              gSaveBlock1Ptr.trainerRematchStepCounter = STEP_COUNTER_MAX;
          else
              gSaveBlock1Ptr.trainerRematchStepCounter++;
      }
}

/** static bool32 IsRematchStepCounterMaxed(void) */
export function IsRematchStepCounterMaxed(): any {
  if (HasAtLeastFiveBadges() && gSaveBlock1Ptr.trainerRematchStepCounter >= STEP_COUNTER_MAX)
          return TRUE;
      else
          return FALSE;
}

/** void TryUpdateRandomTrainerRematches(u16 mapGroup, u16 mapNum) */
export function TryUpdateRandomTrainerRematches(mapGroup: any, mapNum: any): any {
  if (IsRematchStepCounterMaxed() && UpdateRandomTrainerRematches(gRematchTable, mapGroup, mapNum) == TRUE)
          gSaveBlock1Ptr.trainerRematchStepCounter = 0;
}

/** bool32 DoesSomeoneWantRematchIn(u16 mapGroup, u16 mapNum) */
export function DoesSomeoneWantRematchIn(mapGroup: any, mapNum: any): any {
  return DoesSomeoneWantRematchIn_(gRematchTable, mapGroup, mapNum);
}

/** bool32 IsRematchTrainerIn(u16 mapGroup, u16 mapNum) */
export function IsRematchTrainerIn(mapGroup: any, mapNum: any): any {
  return IsRematchTrainerIn_(gRematchTable, mapGroup, mapNum);
}

/** static u16 GetRematchTrainerId(u16 trainerId) */
export function GetRematchTrainerId(trainerId: any): any {
  return GetRematchTrainerIdFromTable(gRematchTable, trainerId);
}

/** u16 GetLastBeatenRematchTrainerId(u16 trainerId) */
export function GetLastBeatenRematchTrainerId(trainerId: any): any {
  return GetLastBeatenRematchTrainerIdFromTable(gRematchTable, trainerId);
}

/** bool8 ShouldTryRematchBattle(void) */
export function ShouldTryRematchBattle(): any {
  if (IsFirstTrainerIdReadyForRematch(gRematchTable, gTrainerBattleOpponent_A))
          return TRUE;

      return WasSecondRematchWon(gRematchTable, gTrainerBattleOpponent_A);
}

/** bool8 IsTrainerReadyForRematch(void) */
export function IsTrainerReadyForRematch(): any {
  return IsTrainerReadyForRematch_(gRematchTable, gTrainerBattleOpponent_A);
}

/** static void HandleRematchVarsOnBattleEnd(void) */
export function HandleRematchVarsOnBattleEnd(): any {
  ClearTrainerWantRematchState(gRematchTable, gTrainerBattleOpponent_A);
      SetBattledTrainersFlags();
}

/** void ShouldTryGetTrainerScript(void) */
export function ShouldTryGetTrainerScript(): any {
  if (sNoOfPossibleTrainerRetScripts > 1)
      {
          sNoOfPossibleTrainerRetScripts = 0;
          sShouldCheckTrainerBScript = TRUE;
          gSpecialVar_Result = TRUE;
      }
      else
      {
          sShouldCheckTrainerBScript = FALSE;
          gSpecialVar_Result = FALSE;
      }
}

/** u16 CountBattledRematchTeams(u16 trainerId) */
export function CountBattledRematchTeams(trainerId: any): any {
  let i: any = null;

      if (HasTrainerBeenFought(gRematchTable[trainerId].trainerIds[0]) != TRUE)
          return 0;

      for (i = 1; i < REMATCHES_COUNT; i++)
      {
          if (gRematchTable[trainerId].trainerIds[i] == 0)
              break;
          if (!HasTrainerBeenFought(gRematchTable[trainerId].trainerIds[i]))
              break;
      }

      return i;
}

